// Sinh ra một âm thanh Pop nhẹ nhàng bằng Web Audio API
// Mang lại cảm giác Premium mà không cần load file mp3 nặng nề
export const playPopSound = () => {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      // Sử dụng sóng hình sin để tạo âm thanh mềm mại, tròn trịa
      osc.type = 'sine';

      // Bắt đầu ở tần số cao rồi rớt nhẹ xuống tạo tiếng "Pop" hay "Tóp"
      osc.frequency.setValueAtTime(600, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.08);

      // Âm lượng (volume) giảm dần nhanh chóng (Fade out)
      gain.gain.setValueAtTime(0.5, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.08);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + 0.08); // Kéo dài rất ngắn chỉ 0.08s
    } catch (e) {
      // Bỏ qua lỗi nếu trình duyệt cấm phát âm thanh khi chưa tương tác
    }
  };
